const { Router } = require('express');
const sessionController = require('../controllers/session.controller');
const playerController = require('../controllers/session-player.controller');
const sessionRules = require('../validators/session.validator');
const playerRules = require('../validators/session-player.validator');
const validate = require('../middlewares/validate');
const requireUser = require('../middlewares/require-user');

const router = Router();

// A host starts a session. The code is generated by the server.
router.post(
  '/',
  requireUser('host'),
  sessionRules.createRules,
  validate,
  sessionController.create
);

// Anyone may read a session by its six-digit code.
router.get(
  '/:code',
  sessionRules.codeParam(),
  validate,
  sessionController.get
);

// Only the host who owns the question set may change the session status.
router.patch(
  '/:code',
  requireUser('host'),
  sessionRules.statusRules,
  validate,
  sessionController.changeStatus
);

// Any signed-in account may join or rejoin.
router.post(
  '/:code/players',
  requireUser(),
  playerRules.joinRules,
  validate,
  playerController.join
);

module.exports = router;